DO $t$ DECLARE u uuid; o uuid:=gen_random_uuid(); o2 uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); c2 uuid:=gen_random_uuid(); cc uuid:=gen_random_uuid(); m text; n text; v integer;
BEGIN
SELECT user_id INTO u FROM public.platform_admins LIMIT 1; SELECT ibge_code INTO m FROM public.municipalities LIMIT 1;
IF u IS NULL OR m IS NULL THEN RAISE EXCEPTION 'Missing fixtures'; END IF;
BEGIN
PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
INSERT INTO public.organizations(id,name,slug,type,created_by) VALUES(o,'Fiscal validation','fv-'||substr(o::text,1,8),'company',u),(o2,'Fiscal validation','fv-'||substr(o2::text,1,8),'company',u);
INSERT INTO public.organization_members(organization_id,user_id,role) VALUES(o,u,'owner'),(o2,u,'owner');
INSERT INTO public.companies(id,organization_id,cnpj,legal_name,municipality_ibge_code,state,created_by,updated_by) VALUES(c,o,'11222333000181','Test',m,'',u,u),(c2,o2,'11222333000181','Test',m,'',u,u),(cc,o,'11444777000161','Cert test',m,'',u,u);
UPDATE public.companies SET cnpj='19131243000197' WHERE id=cc;
IF NOT EXISTS(SELECT 1 FROM public.companies WHERE id=cc AND cnpj='19131243000197') THEN RAISE EXCEPTION 'Editable CNPJ failed'; END IF;
INSERT INTO public.company_fiscal_settings(company_id,organization_id,cnpj,simples_nacional_option,simples_nacional_regime,approx_taxes_mode,created_by,updated_by) VALUES(c,o,'',1,null,'none',u,u),(c2,o2,'',3,1,'none',u,u);
IF (SELECT dps_series FROM public.company_fiscal_settings WHERE company_id=c)<>1 OR (SELECT dps_series FROM public.company_fiscal_settings WHERE company_id=c2)<>2 THEN RAISE EXCEPTION 'Series uniqueness failed'; END IF;
BEGIN UPDATE public.companies SET cnpj='11444777000161' WHERE id=c;RAISE EXCEPTION 'FAIL_cnpj';EXCEPTION WHEN OTHERS THEN IF SQLERRM='FAIL_cnpj' OR position('O CNPJ não pode ser alterado' IN SQLERRM)=0 THEN RAISE;END IF;END;
INSERT INTO public.company_certificates(company_id,organization_id,holder,cnpj,issuer,serial_number,valid_from,valid_until,status,uploaded_by) VALUES(cc,o,'Test','19131243000197','Test','0','2020-01-01','2021-01-01','replaced',u);
BEGIN UPDATE public.companies SET cnpj='11444777000161' WHERE id=cc;RAISE EXCEPTION 'FAIL_history';EXCEPTION WHEN OTHERS THEN IF SQLERRM='FAIL_history' OR position('O CNPJ não pode ser alterado' IN SQLERRM)=0 THEN RAISE;END IF;END;
UPDATE public.company_certificates SET status='active' WHERE company_id=cc;
BEGIN UPDATE public.companies SET cnpj='11444777000161' WHERE id=cc;RAISE EXCEPTION 'FAIL_active';EXCEPTION WHEN OTHERS THEN IF SQLERRM='FAIL_active' OR position('O CNPJ não pode ser alterado' IN SQLERRM)=0 THEN RAISE;END IF;END;
BEGIN UPDATE public.company_fiscal_settings SET simples_nacional_regime=1 WHERE company_id=c;RAISE EXCEPTION 'FAIL_sn';EXCEPTION WHEN check_violation THEN NULL;END;
BEGIN UPDATE public.company_fiscal_settings SET simples_nacional_regime=null WHERE company_id=c2;RAISE EXCEPTION 'FAIL_sn3';EXCEPTION WHEN check_violation THEN NULL;END;
BEGIN UPDATE public.company_fiscal_settings SET approx_taxes_mode='percent_by_sphere',approx_federal_percent=0,approx_state_percent=100 WHERE company_id=c;RAISE EXCEPTION 'FAIL_percent';EXCEPTION WHEN check_violation THEN NULL;END;
UPDATE public.company_fiscal_settings SET approx_taxes_mode='percent_by_sphere',approx_federal_percent=0,approx_state_percent=100,approx_municipal_percent=0 WHERE company_id=c;
BEGIN UPDATE public.company_fiscal_settings SET approx_federal_percent=101 WHERE company_id=c;RAISE EXCEPTION 'FAIL_percent_range';EXCEPTION WHEN check_violation THEN NULL;END;
BEGIN UPDATE public.company_fiscal_settings SET dps_series=50000 WHERE company_id=c;RAISE EXCEPTION 'FAIL_range';EXCEPTION WHEN OTHERS THEN IF SQLERRM='FAIL_range' THEN RAISE;END IF;END;
BEGIN UPDATE public.company_fiscal_settings SET dps_series=2 WHERE company_id=c;RAISE EXCEPTION 'FAIL_unique';EXCEPTION WHEN OTHERS THEN IF SQLERRM='FAIL_unique' OR position('já está reservada' IN SQLERRM)=0 THEN RAISE;END IF;END;
n:=public.reserve_dps_number(c,o,1,'production',u);IF n<>'1' THEN RAISE EXCEPTION 'First number failed';END IF;
-- No issuance occurs. Reserved number remains consumed even if future issuance fails; gap accepted.
n:=public.reserve_dps_number(c,o,1,'production',u);IF n<>'2' THEN RAISE EXCEPTION 'Definitive reservation failed';END IF;
n:=public.reserve_dps_number(c,o,1,'sandbox',u);IF n<>'1' THEN RAISE EXCEPTION 'Environment isolation failed';END IF;
UPDATE public.company_fiscal_settings SET dps_series=49999 WHERE company_id=c;UPDATE public.company_fiscal_settings SET dps_series=1 WHERE company_id=c;
n:=public.reserve_dps_number(c,o,1,'production',u);IF n<>'3' THEN RAISE EXCEPTION 'Reuse series must preserve counter';END IF;
BEGIN UPDATE public.dps_sequences SET next_number=1 WHERE company_id=c AND series=1 AND environment='production';RAISE EXCEPTION 'FAIL_recycle';EXCEPTION WHEN OTHERS THEN IF SQLERRM='FAIL_recycle' OR position('definitivo' IN SQLERRM)=0 THEN RAISE;END IF;END;
UPDATE public.dps_sequences SET next_number=999999999999999 WHERE company_id=c AND series=1 AND environment='production';
n:=public.reserve_dps_number(c,o,1,'production',u);IF n<>'999999999999999' THEN RAISE EXCEPTION 'Maximum failed';END IF;
BEGIN PERFORM public.reserve_dps_number(c,o,1,'production',u);RAISE EXCEPTION 'FAIL_exhausted';EXCEPTION WHEN OTHERS THEN IF SQLERRM='FAIL_exhausted' OR position('esgotada' IN SQLERRM)=0 THEN RAISE;END IF;END;
INSERT INTO public.service_codes VALUES('999998','Ação fiscal de teste','Teste');
SELECT count(*) INTO v FROM public.search_fiscal_catalog('service_codes','acao');IF v<>1 THEN RAISE EXCEPTION 'Accent search failed';END IF;
INSERT INTO public.company_service_profiles(company_id,organization_id,name,service_code,iss_taxation,immunity_type,created_by,updated_by) VALUES(c,o,'Test','999998',2,0,u,u);
BEGIN UPDATE public.company_service_profiles SET immunity_type=null WHERE company_id=c;RAISE EXCEPTION 'FAIL_immunity';EXCEPTION WHEN check_violation THEN NULL;END;
BEGIN INSERT INTO public.company_service_profiles(company_id,organization_id,name,service_code,created_by,updated_by) VALUES(c,o,'Test','999997',u,u);RAISE EXCEPTION 'FAIL_fk';EXCEPTION WHEN foreign_key_violation THEN NULL;END;
DELETE FROM public.platform_admins WHERE user_id=u;
SET LOCAL ROLE authenticated;
UPDATE public.company_fiscal_settings SET special_tax_regime=9 WHERE company_id=c;GET DIAGNOSTICS v=ROW_COUNT;IF v<>1 THEN RAISE EXCEPTION 'Owner edit failed';END IF;
BEGIN UPDATE public.company_fiscal_settings SET dps_series=3 WHERE company_id=c;RAISE EXCEPTION 'FAIL_series_owner';EXCEPTION WHEN OTHERS THEN IF SQLERRM='FAIL_series_owner' OR position('Só o administrador' IN SQLERRM)=0 THEN RAISE;END IF;END;
BEGIN UPDATE public.dps_sequences SET next_number=1 WHERE company_id=c;RAISE EXCEPTION 'FAIL_direct';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
BEGIN INSERT INTO public.service_codes VALUES('999997','Test','Test');RAISE EXCEPTION 'FAIL_catalog_write';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
BEGIN PERFORM public.reserve_dps_number(c,o,1,'sandbox',u);RAISE EXCEPTION 'FAIL_rpc';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
RESET ROLE;UPDATE public.organization_members SET role='admin' WHERE organization_id=o AND user_id=u;
SET LOCAL ROLE authenticated;UPDATE public.company_fiscal_settings SET special_tax_regime=0 WHERE company_id=c;GET DIAGNOSTICS v=ROW_COUNT;IF v<>1 THEN RAISE EXCEPTION 'Admin edit failed';END IF;RESET ROLE;
FOR n IN SELECT unnest(ARRAY['operator','viewer','developer']) LOOP
UPDATE public.organization_members SET role=n::public.org_role WHERE organization_id=o AND user_id=u;SET LOCAL ROLE authenticated;
SELECT count(*) INTO v FROM public.company_fiscal_settings WHERE company_id=c;IF v<>1 THEN RAISE EXCEPTION 'Member read failed';END IF;
UPDATE public.company_fiscal_settings SET special_tax_regime=9 WHERE company_id=c;GET DIAGNOSTICS v=ROW_COUNT;IF v<>0 THEN RAISE EXCEPTION 'Readonly fiscal update allowed';END IF;
UPDATE public.company_service_profiles SET active=false WHERE company_id=c;GET DIAGNOSTICS v=ROW_COUNT;IF v<>0 THEN RAISE EXCEPTION 'Readonly profile update allowed';END IF;RESET ROLE;
END LOOP;
DELETE FROM public.organization_members WHERE organization_id=o AND user_id=u;SET LOCAL ROLE authenticated;
SELECT count(*) INTO v FROM public.company_fiscal_settings WHERE company_id=c;IF v<>0 THEN RAISE EXCEPTION 'Cross tenant settings leak';END IF;
SELECT count(*) INTO v FROM public.company_service_profiles WHERE company_id=c;IF v<>0 THEN RAISE EXCEPTION 'Cross tenant profiles leak';END IF;
RESET ROLE;SET LOCAL ROLE anon;BEGIN PERFORM count(*) FROM public.service_codes;RAISE EXCEPTION 'FAIL_anon';EXCEPTION WHEN insufficient_privilege THEN NULL;END;RESET ROLE;
RAISE EXCEPTION USING ERRCODE='ZX001',MESSAGE='ROLLBACK_TEST_SUCCESS';
EXCEPTION WHEN SQLSTATE 'ZX001' THEN RAISE NOTICE 'All fiscal integration assertions passed; fixtures rolled back.';
END;END $t$;